ody><div id="divHeader"><b>TUTELA ANTECIPADA ANTECEDENTE Nº 4000549-81.2025.8.26.0319/SP<table border="0"><tr><td>RELATOR</td><td>: [PESSOA 10] ANTUNES</td></tr><tr><td>REQUERENTE</td><td>: BRACELL SP CELULOSE LTDA</td></tr><tr><td>ADVOGADO(A)</td><td>: [NOME] ([OAB])</td></tr></table></b></div><div id="divBody"><center><p>ATO ORDINATÓRIO</p></center><br/><p>Intimação realizada no sistema eproc.</p><p>O ato refere-se ao seguinte evento:</p><p>Evento 56 - 19/10/2026 - Juntada de certidão</p></div></body></html>", "numero_processo": "40005498120258260319", "meio": "D", "link": "https://eproc1g.tjsp.jus.br/eproc/externo_controlador.php?acao=consulta_publica_documento&numProcesso=40005498120258260319&idDocumento=611792465202438559733602350916&hash=b969aafa4e1d4e3c4d89d45e2fc4cdebec1e10083ef694e34656fdf26fa81a4e", "tipoDocumento": "Ato ordinatório", "nomeClasse": "[PESSOA 11]", "codigoClasse": "12135", "numeroComunicacao": 66, "ativo": true, "hash": "vLko4Pw1YXBswouoTGjddl6bAKq5Vd", "status": "P", "motivo_cancelamento": null, "data_cancelamento": null, "datadisponibilizacao": "21/10/2026", "meiocompleto": "Diário de Justiça Eletrônico Nacional", "numeroprocessocommascara": "4000549-81.2025.8.26.0319", "destinatarios": [{"comunicacao_id": 762302145, "nome": "[NOME]", "polo": "A"}], "destinatarioadvogados": [{"id": 1435806484, "comunicacao_id": 762302145, "advogado_id": 847990, "created_at": "2026-10-20T00:00:32", "updated_at": "2026-10-20T00:00:32", "advogado": {"id": 847990, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}]}, {"id": 762302205, "data_disponibilizacao": "2026-10-21", "siglaTribunal": "TJSP", "tipoComunicacao": "Intimação", "nomeOrgao": "UPJ da 1ª a 3ª [NOME] - Regional X - Ipiranga", "idOrgao": 100655, "texto": "<html>
