s de integração, deverão entrar em contato com a equipe responsável no TJSP por meio de abertura de chamado; Em caso de dúvidas, abra um chamado em https://www.suportesistemastjsp.com.br/. As comunicações subsequentes serão realizadas pelo sistema eproc, nos termos da legislação vigente e das Resoluções do CNJ aplicáveis. - ADV: [NOME] ([OAB]/SP), [NOME] ([OAB]/SP), [NOME] ([OAB]/SP)", "numero_processo": "00164137420268260100", "meio": "D", "link": "https://www.dje.tjsp.jus.br", "tipoDocumento": "Intimação", "nomeClasse": "CUMPRIMENTO PROVISóRIO DE SENTENçA", "codigoClasse": "157", "numeroComunicacao": 490, "ativo": true, "hash": "jqlwEO1dZOXs3dsnTX377WYDGMoWQn", "status": "P", "motivo_cancelamento": null, "data_cancelamento": null, "datadisponibilizacao": "21/10/2026", "meiocompleto": "Diário de Justiça Eletrônico Nacional", "numeroprocessocommascara": "0016413-74.2026.8.26.0100", "destinatarios": [{"comunicacao_id": 762303006, "nome": "[NOME]", "polo": "P"}, {"comunicacao_id": 762303006, "nome": "[NOME]", "polo": "P"}, {"comunicacao_id": 762303006, "nome": "[NOME]", "polo": "A"}], "destinatarioadvogados": [{"id": 1435808099, "comunicacao_id": 762303006, "advogado_id": 3879856, "created_at": "2026-10-20T00:02:56", "updated_at": "2026-10-20T00:02:56", "advogado": {"id": 3879856, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}, {"id": 1435808098, "comunicacao_id": 762303006, "advogado_id": 1874421, "created_at": "2026-10-20T00:02:56", "updated_at": "2026-10-20T00:02:56", "advogado": {"id": 1874421, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}]}, {"id": 762303018, "data_disponibilizacao": "2026-10-21", "siglaTribunal": "TJSP", "tipoComunicacao": "Intimação", "nomeOrgao": "UPJ da 26ª a 30ª [NOME] - [NOME] Cível", "idOrgao": 98517, "texto": "<html>
