        <div class="content-wrapper">
          <p class="ql-align-justify">EDITAL&nbsp;PARA&nbsp;CIÊNCIA&nbsp;DE&nbsp;ELIMINAÇÃO&nbsp;DE&nbsp;AUTOS&nbsp;DIGITALIZADOS&nbsp;Nº&nbsp;<span class="no-break" data-nobreak="true">0024529&#x2011;07.2005.8.26.0003</span>,&nbsp;COM&nbsp;PRAZO&nbsp;DE&nbsp;30&nbsp;(TRINTA)&nbsp;DIAS,&nbsp;expedido&nbsp;no&nbsp;presente&nbsp;Expediente&nbsp;Administrativo&nbsp;nº&nbsp;<span class="no-break" data-nobreak="true">0003204&#x2011;09.2024.8.26.0003</span>.&nbsp;O(A)&nbsp;MM(a).&nbsp;Juiz(a)&nbsp;de&nbsp;Direito&nbsp;da&nbsp;1ª&nbsp;Vara&nbsp;Cível,&nbsp;do&nbsp;Foro&nbsp;Regional&nbsp;III&nbsp;-&nbsp;Jabaquara,&nbsp;Estado&nbsp;de&nbsp;São&nbsp;Paulo,&nbsp;Dr(a).&nbsp;[PESSOA 79],&nbsp;na&nbsp;forma&nbsp;da&nbsp;Lei,&nbsp;etc..&nbsp;FAZ&nbsp;SABER&nbsp;aos&nbsp;interessados,&nbsp;seus&nbsp;procuradores&nbsp;e&nbsp;a&nbsp;todos&nbsp;quantos&nbsp;possa&nbsp;interessar&nbsp;que,&nbsp;a&nbsp;partir&nbsp;do&nbsp;30º&nbsp;(trigésimo)&nbsp;dia&nbsp;corrido&nbsp;subsequente&nbsp;à&nbsp;data&nbsp;de&nbsp;publicação&nbsp;deste&nbsp;edital&nbsp;no&nbsp;Diário&nbsp;da&nbsp;Justiça&nbsp;Eletrônico,&nbsp;este&nbsp;Juízo&nbsp;e&nbsp;respectivo&nbsp;Cartório,&nbsp;eliminará&nbsp;os&nbsp;autos&nbsp;físicos&nbsp;&nbsp;que&nbsp;foram&nbsp;digitalizados&nbsp;para&nbsp;tramitação&nbsp;eletrônica,&nbsp;de&nbsp;acordo&nbsp;com&nbsp;a&nbsp;Resolução&nbsp;TJSP&nbsp;859/2021.&nbsp;Durante&nbsp;esse&nbsp;período,&nbsp;os&nbsp;interessados&nbsp;pela&nbsp;guarda&nbsp;definitiva&nbsp;do&nbsp;fragmento&nbsp;de&nbsp;processo,&nbsp;às&nbsp;suas&nbsp;expensas,&nbsp;poderão&nbsp;requerer&nbsp;sua&nbsp;posse,&nbsp;conforme&nbsp;modelo&nbsp;3&nbsp;contido&nbsp;no&nbsp;Comunicado&nbsp;Conjunto&nbsp;nº&nbsp;698/2023&nbsp;disponibilizado&nbsp;no&nbsp;DJE,&nbsp;data&nbsp;29/09/2023&nbsp;-&nbsp;fls.&nbsp;02&nbsp;a&nbsp;05,&nbsp;encaminhando&nbsp;o&nbsp;“Pedido&nbsp;de&nbsp;Guarda&nbsp;Definitiva&nbsp;de&nbsp;Autos&nbsp;Físicos&nbsp;Digitalizados”&nbsp;exclusivamente&nbsp;por&nbsp;meio&nbsp;de&nbsp;mensagem&nbsp;eletrônica&nbsp;ao&nbsp;endereço&nbsp;upj1a6cvjabaquara@tjsp.jus.br.&nbsp;Os&nbsp;solicitantes&nbsp;terão&nbsp;o&nbsp;prazo&nbsp;de&nbsp;10&nbsp;(dez)&nbsp;dias&nbsp;úteis&nbsp;para&nbsp;retirada&nbsp;dos&nbsp;autos,&nbsp;após&nbsp;contato&nbsp;via&nbsp;e&#x2011;mail&nbsp;pela&nbsp;Unidade&nbsp;comunicando&nbsp;que&nbsp;os&nbsp;autos&nbsp;estão&nbsp;disponíveis&nbsp;para&nbsp;retirada.&nbsp;Decorrido&nbsp;o&nbsp;prazo&nbsp;e&nbsp;não&nbsp;retirados,&nbsp;os&nbsp;autos&nbsp;serão&nbsp;encaminhados&nbsp;para&nbsp;descarte.&nbsp;Classe:&nbsp;Tutela&nbsp;Cautelar&nbsp;Antecedente&nbsp;-&nbsp;Autor/Exequente:&nbsp;[PESSOA 80];&nbsp;Requerido/Executado:&nbsp;[PESSOA 81];&nbsp;ADVOGADOS:&nbsp;[PESSOA 82]&nbsp;de&nbsp;Sousa&nbsp;OAB&nbsp;207013/SP;&nbsp;[PESSOA 83]&nbsp;de&nbsp;Sant´ana&nbsp;Neto&nbsp;OAB&nbsp;76457/SP;&nbsp;[PESSOA 84]&nbsp;OAB&nbsp;117173/SP.&nbsp;Volumes:&nbsp;3.&nbsp;Será&nbsp;o&nbsp;presente&nbsp;edital,&nbsp;por&nbsp;extrato,&nbsp;afixado&nbsp;e&nbsp;publicado&nbsp;na&nbsp;forma&nbsp;da&nbsp;lei.</p>
        </div>", "numero_processo": "00245290720058260003", "meio": "E", "link": "https://esaj.tjsp.jus.br", "tipoDocumento": "Edital", "nomeClasse": "TUTELA CAUTELAR ANTECEDENTE", "codigoClasse": "12134", "numeroComunicacao": 559, "ativo": true, "hash": "PpDAj7XqYvOsNOfvhny44xRrvMJbg1", "status": "P", "motivo_cancelamento": null, "data_cancelamento": null, "datadisponibilizacao": "21/10/2026", "meiocompleto": "Plataforma Nacional de Editais", "numeroprocessocommascara": "0024529-07.2005.8.26.0003", "destinatarios": [{"comunicacao_id": 762682988, "nome": "[NOME]", "polo": "P"}, {"comunicacao_id": 762682988, "nome": "[NOME]", "polo": "A"}], "destinatarioadvogados": [{"id": 1436621615, "comunicacao_id": 762682988, "advogado_id": 4943478, "created_at": "2026-10-20T11:47:01", "updated_at": "2026-10-20T11:47:01", "advogado": {"id": 4943478, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}, {"id": 1436621614, "comunicacao_id": 762682988, "advogado_id": 4943477, "created_at": "2026-10-20T11:47:01", "updated_at": "2026-10-20T11:47:01", "advogado": {"id": 4943477, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}, {"id": 1436621613, "comunicacao_id": 762682988, "advogado_id": 4593949, "created_at": "2026-10-20T11:47:01", "updated_at": "2026-10-20T11:47:01", "advogado": {"id": 4593949, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}]}, {"id": 762303136, "data_disponibilizacao": "2026-10-21", "siglaTribunal": "TJSP", "tipoComunicacao": "Intimação", "nomeOrgao": "UPJ da 5ª a 8ª e 15ª [NOME] - Regional II - [NOME]", "idOrgao": 100590, "texto": "<html>
